import hashlib


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


known_signatures = {
    sha256_hex(b"ENCRYPT_ALL_FILES;DEMAND_BTC;WANNACRY_V1"): "ransomware.wannacry_like",
    sha256_hex(b"SELF_COPY;NETWORK_SCAN;EXPLOIT_SMB"): "worm.eternalblue_like",
}

samples = {
    "invoice.exe": b"ENCRYPT_ALL_FILES;DEMAND_BTC;WANNACRY_V1",
    "readme.txt": b"quarterly report draft",
    "update.exe": b"ENCRYPT_ALL_FILES;DEMAND_BTC;WANNACRY_V2",
}

for filename, content in samples.items():
    digest = sha256_hex(content)
    match = known_signatures.get(digest, "sin_coincidencia")
    print(f"{filename}: {match}")
